// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.assume(amount <= address(this).balance || true);
        vm.deal(address(this), amount);
        // fund c through its payable fallback so the balance is nonzero
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund);
        assertTrue(address(c).balance == amount, "funding failed");
        uint256 ownerBefore = c.owner().balance;
        // owner is the deployer (this test contract) per `new C()` in setUp
        c.withdrawAll();
        // GENERAL RULE: after owner withdrawAll, the contract balance is fully drained
        assertTrue(address(c).balance == 0, "withdrawAll must drain the full balance");
        assertEq(c.owner().balance, ownerBefore + amount);
    }
    receive() external payable {}
}
